import React, { useState, useEffect } from 'react';

const Dashboard = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حركة خفيفة للصورة بناءً على الماوس
    const x = (e.clientX / innerWidth - 0.5) * 30;
    const y = (e.clientY / innerHeight - 0.5) * 30;
    setOffset({ x, y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // دوال للتعامل مع الأزرار
  const handlePropertiesClick = () => {
    document.querySelector('button[title="العقارات"]')?.click();
  };

  const handleContactClick = () => {
    const fab = document.querySelector('.contact-fab');
    if (fab) fab.click();
  };

  const handleLoginClick = () => {
    const btn = document.querySelector('#client-login-button');
    if (btn) btn.click();
  };

  return (
    <div className="container-fluid p-0 overflow-hidden" style={{ minHeight: '80vh' }}>
      <div className="row g-0 align-items-center" style={{ minHeight: '80vh' }}>
        
        {/* القسم النصي */}
        <div className="col-lg-6 p-5 fade-in" style={{ zIndex: 2 }}>
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4" style={{ background: 'linear-gradient(45deg, #667eea, #764ba2)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              مستقبل العقارات <br/> بين يديك
            </h1>
            <p className="lead text-muted mb-5" style={{ lineHeight: '1.8' }}>
              منصة <strong>سمسار برو</strong> هي الحل الأمثل لإدارة وتسويق العقارات بذكاء. 
              نجمع بين التكنولوجيا الحديثة وسهولة الاستخدام لنوفر لك تجربة فريدة.
            </p>
            
            <div className="d-flex gap-3 flex-wrap">
              <button className="btn btn-primary btn-lg px-4 rounded-pill shadow-lg" onClick={handlePropertiesClick}>
                تصفح العقارات
              </button>
              <button className="btn btn-outline-secondary btn-lg px-4 rounded-pill" onClick={handleContactClick}>
                تواصل معنا
              </button>
              <button className="btn btn-success btn-lg px-4 rounded-pill shadow-lg" onClick={handleLoginClick}>
                سجل دخولك الآن
              </button>
            </div>

            <div className="mt-5 pt-4 border-top">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-primary">+500</h3>
                  <small className="text-muted">عقار متاح</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+100</h3>
                  <small className="text-muted">عميل سعيد</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">24/7</h3>
                  <small className="text-muted">دعم فني</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* القسم التفاعلي 3D */}
        <div className="col-lg-6 d-flex justify-content-center align-items-center position-relative" style={{ height: '80vh', perspective: '1000px' }}>
          <div 
            className="house-image-wrapper"
            style={{
              transform: `rotateY(${offset.x / 2}deg) rotateX(${-offset.y / 2}deg)`,
              transition: 'transform 0.1s ease-out',
            }}
          >
            <img 
              src="https://images.unsplash.com/photo-1580587771525-78b9dba3b91d?ixlib=rb-1.2.1&auto=format&fit=crop&w=1000&q=80" 
              alt="Modern House" 
              className="img-fluid rounded-4 shadow-lg"
              style={{
                  maxHeight: '60vh',
                  border: '10px solid rgba(255,255,255,0.3)',
                  boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.4)'
              }}
            />
          </div>
        </div>
      </div>

      <style>{``}</style>
    </div>
  );
};

export default Dashboard;
